CREATE TYPE public.app_role AS ENUM ('job_seeker','mentor','employer','admin');
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) FROM public,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin')));
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', headline text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', biography text NOT NULL DEFAULT '', avatar_url text, education text NOT NULL DEFAULT '', work_experience text NOT NULL DEFAULT '', skills text[] NOT NULL DEFAULT '{}', career_interests text[] NOT NULL DEFAULT '{}', industries text[] NOT NULL DEFAULT '{}', employment_status text NOT NULL DEFAULT 'Seeking opportunities', certifications text NOT NULL DEFAULT '', career_goals text NOT NULL DEFAULT '', portfolio_url text NOT NULL DEFAULT '', employer_visible boolean NOT NULL DEFAULT true, terms_accepted boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING (id=(select auth.uid()) OR (employer_visible AND (select public.has_role((select auth.uid()),'employer'))) OR (select public.has_role((select auth.uid()),'admin')));
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=(select auth.uid())) WITH CHECK (id=(select auth.uid()));
CREATE FUNCTION public.handle_new_bridgeup_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE chosen public.app_role; BEGIN chosen:=CASE WHEN NEW.raw_user_meta_data->>'account_type'='mentor' THEN 'mentor'::public.app_role WHEN NEW.raw_user_meta_data->>'account_type'='employer' THEN 'employer'::public.app_role ELSE 'job_seeker'::public.app_role END; INSERT INTO public.profiles(id,full_name,location,terms_accepted) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',''),coalesce(NEW.raw_user_meta_data->>'location',''),coalesce((NEW.raw_user_meta_data->>'terms_accepted')::boolean,false)); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,chosen); RETURN NEW; END $$;
CREATE TRIGGER bridgeup_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_bridgeup_user();
CREATE TABLE public.organisations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE UNIQUE, name text NOT NULL, website text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', verified boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE ON public.organisations TO authenticated; GRANT ALL ON public.organisations TO service_role; ALTER TABLE public.organisations ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_read ON public.organisations FOR SELECT TO authenticated USING (true);
CREATE POLICY org_insert ON public.organisations FOR INSERT TO authenticated WITH CHECK (owner_id=(select auth.uid()) AND NOT verified AND (select public.has_role((select auth.uid()),'employer')));
CREATE POLICY org_update ON public.organisations FOR UPDATE TO authenticated USING (owner_id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin'))) WITH CHECK (owner_id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin')));
CREATE FUNCTION public.guard_org_verification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.verified IS DISTINCT FROM OLD.verified AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Only administrators can verify organisations'; END IF; RETURN NEW; END $$;
CREATE TRIGGER org_verification BEFORE UPDATE ON public.organisations FOR EACH ROW EXECUTE FUNCTION public.guard_org_verification();
CREATE TABLE public.opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, organisation text NOT NULL, type text NOT NULL DEFAULT 'Internship' CHECK (type IN ('Internship','Fellowship','Returnship','Graduate programme','Entry-level job')), location text NOT NULL, arrangement text NOT NULL DEFAULT 'Hybrid' CHECK (arrangement IN ('Remote','Hybrid','On-site')), skills text[] NOT NULL DEFAULT '{}', description text NOT NULL DEFAULT '', salary text NOT NULL DEFAULT '', deadline date NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','published','closed','rejected')), sample boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.opportunities TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.opportunities TO authenticated; GRANT ALL ON public.opportunities TO service_role; ALTER TABLE public.opportunities ENABLE ROW LEVEL SECURITY;
CREATE INDEX opportunities_owner_idx ON public.opportunities(owner_id,created_at DESC);
CREATE POLICY opp_anon ON public.opportunities FOR SELECT TO anon USING(status='published');
CREATE POLICY opp_read ON public.opportunities FOR SELECT TO authenticated USING(status='published' OR owner_id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin')));
CREATE POLICY opp_insert ON public.opportunities FOR INSERT TO authenticated WITH CHECK(owner_id=(select auth.uid()) AND status='pending' AND NOT sample AND (select public.has_role((select auth.uid()),'employer')));
CREATE POLICY opp_update ON public.opportunities FOR UPDATE TO authenticated USING(owner_id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin'))) WITH CHECK(owner_id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin')));
CREATE POLICY opp_delete ON public.opportunities FOR DELETE TO authenticated USING(owner_id=(select auth.uid()) OR (select public.has_role((select auth.uid()),'admin')));
CREATE FUNCTION public.guard_opportunity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status NOT IN ('pending','closed') THEN RAISE EXCEPTION 'Only administrators can publish opportunities'; END IF; IF NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.sample IS DISTINCT FROM OLD.sample THEN RAISE EXCEPTION 'Cannot change ownership'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER opp_guard BEFORE UPDATE ON public.opportunities FOR EACH ROW EXECUTE FUNCTION public.guard_opportunity();
CREATE TABLE public.applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, opportunity_id uuid NOT NULL REFERENCES public.opportunities(id) ON DELETE CASCADE, cover_letter text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Submitted' CHECK(status IN ('Submitted','Under Review','Shortlisted','Interview','Accepted','Rejected','Withdrawn')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,opportunity_id));
GRANT SELECT,INSERT,UPDATE ON public.applications TO authenticated; GRANT ALL ON public.applications TO service_role; ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
CREATE INDEX applications_opportunity_idx ON public.applications(opportunity_id); CREATE INDEX applications_user_idx ON public.applications(user_id,created_at DESC);
CREATE POLICY app_read ON public.applications FOR SELECT TO authenticated USING(user_id=(select auth.uid()) OR opportunity_id IN (SELECT id FROM public.opportunities WHERE owner_id=(select auth.uid())) OR (select public.has_role((select auth.uid()),'admin')));
CREATE POLICY app_insert ON public.applications FOR INSERT TO authenticated WITH CHECK(user_id=(select auth.uid()) AND status='Submitted' AND (select public.has_role((select auth.uid()),'job_seeker')) AND EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND o.status='published' AND o.deadline>=CURRENT_DATE));
CREATE POLICY app_update ON public.applications FOR UPDATE TO authenticated USING(user_id=(select auth.uid()) OR opportunity_id IN(SELECT id FROM public.opportunities WHERE owner_id=(select auth.uid()))) WITH CHECK(user_id=(select auth.uid()) OR opportunity_id IN(SELECT id FROM public.opportunities WHERE owner_id=(select auth.uid())));
CREATE FUNCTION public.guard_application() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.opportunity_id IS DISTINCT FROM OLD.opportunity_id THEN RAISE EXCEPTION 'Cannot change application ownership'; END IF; IF auth.uid()=OLD.user_id AND NEW.status IS DISTINCT FROM OLD.status AND NEW.status<>'Withdrawn' THEN RAISE EXCEPTION 'Applicants may only withdraw applications'; END IF; RETURN NEW; END $$;
CREATE TRIGGER application_guard BEFORE UPDATE ON public.applications FOR EACH ROW EXECUTE FUNCTION public.guard_application();
CREATE TABLE public.saved_opportunities (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, opportunity_id uuid NOT NULL REFERENCES public.opportunities(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,opportunity_id));
GRANT SELECT,INSERT,DELETE ON public.saved_opportunities TO authenticated; GRANT ALL ON public.saved_opportunities TO service_role; ALTER TABLE public.saved_opportunities ENABLE ROW LEVEL SECURITY;
CREATE INDEX saved_opp_idx ON public.saved_opportunities(opportunity_id);
CREATE POLICY saved_read ON public.saved_opportunities FOR SELECT TO authenticated USING(user_id=(select auth.uid())); CREATE POLICY saved_insert ON public.saved_opportunities FOR INSERT TO authenticated WITH CHECK(user_id=(select auth.uid()) AND (select public.has_role((select auth.uid()),'job_seeker'))); CREATE POLICY saved_delete ON public.saved_opportunities FOR DELETE TO authenticated USING(user_id=(select auth.uid()));
CREATE TABLE public.mentor_listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL, title text NOT NULL, organisation text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', expertise text[] NOT NULL DEFAULT '{}', biography text NOT NULL DEFAULT '', available boolean NOT NULL DEFAULT true, sample boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.mentor_listings TO anon; GRANT SELECT,INSERT,UPDATE ON public.mentor_listings TO authenticated; GRANT ALL ON public.mentor_listings TO service_role; ALTER TABLE public.mentor_listings ENABLE ROW LEVEL SECURITY;
CREATE POLICY mentors_public ON public.mentor_listings FOR SELECT TO anon,authenticated USING(true); CREATE POLICY mentors_insert ON public.mentor_listings FOR INSERT TO authenticated WITH CHECK(user_id=(select auth.uid()) AND NOT sample AND (select public.has_role((select auth.uid()),'mentor'))); CREATE POLICY mentors_update ON public.mentor_listings FOR UPDATE TO authenticated USING(user_id=(select auth.uid())) WITH CHECK(user_id=(select auth.uid()) AND NOT sample);
CREATE TABLE public.mentorships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), seeker_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, mentor_id uuid NOT NULL REFERENCES public.mentor_listings(id) ON DELETE CASCADE, message text NOT NULL, status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Active','Declined','Completed')), goals text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(seeker_id,mentor_id));
GRANT SELECT,INSERT,UPDATE ON public.mentorships TO authenticated; GRANT ALL ON public.mentorships TO service_role; ALTER TABLE public.mentorships ENABLE ROW LEVEL SECURITY;
CREATE INDEX mentorship_mentor_idx ON public.mentorships(mentor_id); CREATE INDEX mentorship_seeker_idx ON public.mentorships(seeker_id,created_at DESC);
CREATE POLICY mentorship_read ON public.mentorships FOR SELECT TO authenticated USING(seeker_id=(select auth.uid()) OR mentor_id IN(SELECT id FROM public.mentor_listings WHERE user_id=(select auth.uid())));
CREATE POLICY mentorship_insert ON public.mentorships FOR INSERT TO authenticated WITH CHECK(seeker_id=(select auth.uid()) AND status='Pending' AND (select public.has_role((select auth.uid()),'job_seeker')) AND EXISTS(SELECT 1 FROM public.mentor_listings m WHERE m.id=mentor_id AND m.available AND NOT m.sample));
CREATE POLICY mentorship_update ON public.mentorships FOR UPDATE TO authenticated USING(mentor_id IN(SELECT id FROM public.mentor_listings WHERE user_id=(select auth.uid()))) WITH CHECK(mentor_id IN(SELECT id FROM public.mentor_listings WHERE user_id=(select auth.uid())));
CREATE POLICY mentor_profile_read ON public.profiles FOR SELECT TO authenticated USING(id IN(SELECT seeker_id FROM public.mentorships WHERE mentor_id IN(SELECT id FROM public.mentor_listings WHERE user_id=(select auth.uid()))));
CREATE TABLE public.sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mentorship_id uuid NOT NULL REFERENCES public.mentorships(id) ON DELETE CASCADE, scheduled_at timestamptz NOT NULL, meeting_url text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', feedback text NOT NULL DEFAULT '', completed boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE ON public.sessions TO authenticated; GRANT ALL ON public.sessions TO service_role; ALTER TABLE public.sessions ENABLE ROW LEVEL SECURITY; CREATE INDEX sessions_mentorship_idx ON public.sessions(mentorship_id,scheduled_at);
CREATE POLICY sessions_read ON public.sessions FOR SELECT TO authenticated USING(mentorship_id IN(SELECT id FROM public.mentorships)); CREATE POLICY sessions_insert ON public.sessions FOR INSERT TO authenticated WITH CHECK(mentorship_id IN(SELECT ms.id FROM public.mentorships ms JOIN public.mentor_listings m ON m.id=ms.mentor_id WHERE m.user_id=(select auth.uid()) AND ms.status='Active')); CREATE POLICY sessions_update ON public.sessions FOR UPDATE TO authenticated USING(mentorship_id IN(SELECT ms.id FROM public.mentorships ms JOIN public.mentor_listings m ON m.id=ms.mentor_id WHERE m.user_id=(select auth.uid()))) WITH CHECK(mentorship_id IN(SELECT ms.id FROM public.mentorships ms JOIN public.mentor_listings m ON m.id=ms.mentor_id WHERE m.user_id=(select auth.uid())));
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL DEFAULT '', read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY; CREATE INDEX notifications_user_idx ON public.notifications(user_id,created_at DESC);
CREATE POLICY notifications_read ON public.notifications FOR SELECT TO authenticated USING(user_id=(select auth.uid())); CREATE POLICY notifications_update ON public.notifications FOR UPDATE TO authenticated USING(user_id=(select auth.uid())) WITH CHECK(user_id=(select auth.uid()));
CREATE FUNCTION public.notify_application() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.notifications(user_id,title,body) VALUES(NEW.user_id,'Application update',NEW.status||' — '||(SELECT title FROM public.opportunities WHERE id=NEW.opportunity_id)); END IF; RETURN NEW; END $$;
CREATE TRIGGER application_notification AFTER UPDATE ON public.applications FOR EACH ROW EXECUTE FUNCTION public.notify_application();
CREATE FUNCTION public.notify_mentorship() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.notifications(user_id,title,body) SELECT user_id,'New mentorship request',NEW.message FROM public.mentor_listings WHERE id=NEW.mentor_id; ELSIF NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.notifications(user_id,title,body) VALUES(NEW.seeker_id,'Mentorship response','Your mentorship request is now '||NEW.status); END IF; RETURN NEW; END $$;
CREATE TRIGGER mentorship_notification AFTER INSERT OR UPDATE ON public.mentorships FOR EACH ROW EXECUTE FUNCTION public.notify_mentorship();
CREATE TABLE public.portfolio_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, description text NOT NULL DEFAULT '', url text NOT NULL DEFAULT '', skills text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.portfolio_projects TO authenticated; GRANT ALL ON public.portfolio_projects TO service_role; ALTER TABLE public.portfolio_projects ENABLE ROW LEVEL SECURITY; CREATE INDEX projects_user_idx ON public.portfolio_projects(user_id,created_at DESC);
CREATE POLICY projects_read ON public.portfolio_projects FOR SELECT TO authenticated USING(user_id=(select auth.uid()) OR user_id IN(SELECT id FROM public.profiles WHERE employer_visible)); CREATE POLICY projects_insert ON public.portfolio_projects FOR INSERT TO authenticated WITH CHECK(user_id=(select auth.uid())); CREATE POLICY projects_update ON public.portfolio_projects FOR UPDATE TO authenticated USING(user_id=(select auth.uid())) WITH CHECK(user_id=(select auth.uid())); CREATE POLICY projects_delete ON public.portfolio_projects FOR DELETE TO authenticated USING(user_id=(select auth.uid()));
CREATE TABLE public.profile_documents (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, cv_path text NOT NULL, employer_visible boolean NOT NULL DEFAULT true);
GRANT SELECT,INSERT,UPDATE ON public.profile_documents TO authenticated; GRANT ALL ON public.profile_documents TO service_role; ALTER TABLE public.profile_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_read ON public.profile_documents FOR SELECT TO authenticated USING(user_id=(select auth.uid()) OR (employer_visible AND user_id IN(SELECT user_id FROM public.applications WHERE opportunity_id IN(SELECT id FROM public.opportunities WHERE owner_id=(select auth.uid())))));
CREATE POLICY documents_insert ON public.profile_documents FOR INSERT TO authenticated WITH CHECK(user_id=(select auth.uid())); CREATE POLICY documents_update ON public.profile_documents FOR UPDATE TO authenticated USING(user_id=(select auth.uid())) WITH CHECK(user_id=(select auth.uid()));
