('Marketing Graduate Trainee','Greenline','Graduate programme','Mombasa, Kenya','On-site',ARRAY['Communication','Marketing','Content Writing'],'Start your marketing career with a structured graduate programme. Gain hands-on campaign experience, training, and professional mentorship.','KES 45,000 / month','2027-03-01','published',true),
('Software Engineering Intern','PayForward','Internship','Nairobi, Kenya','Hybrid',ARRAY['JavaScript','React','Git'],'Build inclusive financial tools alongside a supportive engineering team. Work on front-end features, collaborate in code reviews, and learn modern development practices.','Paid internship','2027-03-10','published',true),
('Finance Returnship','Kijani Partners','Returnship','Kampala, Uganda','Hybrid',ARRAY['Excel','Finance','Analysis'],'Return to the workplace with a flexible sixteen-week programme, a dedicated mentor, and skills refreshers. Career gaps are welcome.','Paid returnship','2027-02-28','published',true),
